import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './ProjectFileModal.css';

const ProjectFileModal = ({ project, isOpen, onClose, onUpdate }) => {
  const [files, setFiles] = useState([]);
  const [folders, setFolders] = useState([]);
  const [loading, setLoading] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [error, setError] = useState(null);
  const [selectedFolder, setSelectedFolder] = useState('root');
  const [isPublic, setIsPublic] = useState(project?.is_public || true);
  const [savingPrivacy, setSavingPrivacy] = useState(false);

  useEffect(() => {
    if (isOpen && project) {
      fetchFiles();
      setIsPublic(project.is_public || true);
    }
  }, [isOpen, project]);

  const fetchFiles = async () => {
    try {
      setLoading(true);
      setError(null);
      const response = await axios.get(`/api/projects/${project.id}/files`, {
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('access_token')}`
        }
      });
      setFiles(response.data.files || []);
      setFolders(response.data.folders || []);
    } catch (error) {
      setError('Ошибка загрузки файлов');
    } finally {
      setLoading(false);
    }
  };


  const handleFileUpload = async (event) => {
    const filesToUpload = Array.from(event.target.files);
    if (filesToUpload.length === 0) return;

    setUploading(true);
    setError(null);

    try {
      for (const file of filesToUpload) {
        const formData = new FormData();
        formData.append('file', file);

        await axios.post(`/api/projects/${project.id}/files?folder=${selectedFolder}`, formData, {
          headers: {
            'Authorization': `Bearer ${localStorage.getItem('access_token')}`,
            'Content-Type': 'multipart/form-data'
          }
        });
      }

      await fetchFiles();
      if (onUpdate) onUpdate();
    } catch (error) {
      setError(error.response?.data?.detail || 'Ошибка загрузки файлов');
    } finally {
      setUploading(false);
    }
  };

  const handleFileDelete = async (filename, folder) => {
    if (!window.confirm('Вы уверены, что хотите удалить этот файл?')) return;

    try {
      await axios.delete(`/api/projects/${project.id}/files?filename=${encodeURIComponent(filename)}&folder=${folder}`, {
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('access_token')}`
        }
      });

      await fetchFiles();
      if (onUpdate) onUpdate();
    } catch (error) {
      setError('Ошибка удаления файла');
    }
  };

  const handleDownload = async (file) => {
    try {
      const response = await axios.get(`/api/projects/${project.id}/files/download?filename=${encodeURIComponent(file.original_name)}&folder=${file.folder}`, {
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('access_token')}`
        },
        responseType: 'blob'
      });

      const url = window.URL.createObjectURL(new Blob([response.data]));
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute('download', file.original_name);
      document.body.appendChild(link);
      link.click();
      link.remove();
      window.URL.revokeObjectURL(url);
    } catch (error) {
      setError('Ошибка скачивания файла');
    }
  };

  const handlePrivacyChange = async (newIsPublic) => {
    try {
      setSavingPrivacy(true);
      await axios.put(`/api/projects/${project.id}/privacy`, {
        is_public: newIsPublic
      }, {
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('access_token')}`
        }
      });

      setIsPublic(newIsPublic);
      if (onUpdate) onUpdate();
    } catch (error) {
      setError('Ошибка обновления настроек приватности');
    } finally {
      setSavingPrivacy(false);
    }
  };


  const formatFileSize = (bytes) => {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  const getFileIcon = (filename) => {
    const extension = filename.split('.').pop().toLowerCase();
    switch (extension) {
      case 'jpg':
      case 'jpeg':
      case 'png':
      case 'gif':
      case 'webp':
        return '🖼️';
      case 'pdf':
        return '📄';
      case 'doc':
      case 'docx':
        return '📝';
      case 'xls':
      case 'xlsx':
        return '📊';
      case 'zip':
      case 'rar':
        return '📦';
      case 'mp4':
      case 'avi':
      case 'mov':
        return '🎥';
      case 'mp3':
      case 'wav':
        return '🎵';
      case 'html':
      case 'htm':
        return '🌐';
      case 'css':
        return '🎨';
      case 'js':
        return '⚡';
      default:
        return '📄';
    }
  };

  if (!isOpen) return null;

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="project-file-modal" onClick={(e) => e.stopPropagation()}>
        <div className="modal-header">
          <h2>Файлы проекта: {project.title}</h2>
          <button className="close-btn" onClick={onClose}>×</button>
        </div>

        <div className="modal-content">
          <div className="file-actions">
            <div className="upload-section">
              <div className="folder-selector">
                <label>Папка для загрузки:</label>
                <select 
                  value={selectedFolder} 
                  onChange={(e) => setSelectedFolder(e.target.value)}
                >
                  <option value="root">Корневая папка</option>
                  <option value="images">Images</option>
                </select>
              </div>
              <label className="upload-btn">
                <input
                  type="file"
                  multiple
                  onChange={handleFileUpload}
                  disabled={uploading}
                />
                {uploading ? 'Загрузка...' : 'Добавить файлы'}
              </label>
            </div>
          </div>

          {error && (
            <div className="error-message">{error}</div>
          )}

          <div className="content-wrapper">
            <div className="files-section">
              {loading ? (
                <div className="loading">Загрузка файлов...</div>
              ) : files.length === 0 ? (
                <div className="no-files">Файлы не найдены</div>
              ) : (
                <div className="folders-container">
                  {folders.map((folder) => (
                    <div key={folder} className="folder-section">
                      <h4 className="folder-title">
                        {folder === 'root' ? '📁 Корневая папка' : '🖼️ Images'}
                      </h4>
                      <div className="items-list">
                        {files
                          .filter(file => file.folder === folder)
                          .length > 0 ? (
                          files
                            .filter(file => file.folder === folder)
                            .map((file, index) => (
                              <div key={`file-${index}`} className="file-item">
                                <div className="file-info">
                                  <span className="file-icon">{getFileIcon(file.original_name)}</span>
                                  <div className="file-details">
                                    <div className="file-name">{file.original_name}</div>
                                    <div className="file-meta">
                                      {formatFileSize(file.size)} • 
                                      {new Date(file.last_modified).toLocaleDateString()}
                                    </div>
                                  </div>
                                </div>
                                <div className="file-actions">
                                  <button 
                                    className="download-btn"
                                    onClick={() => handleDownload(file)}
                                    title="Скачать"
                                  >
                                    ⬇️
                                  </button>
                                  <button 
                                    className="delete-btn"
                                    onClick={() => handleFileDelete(file.original_name, file.folder)}
                                    title="Удалить"
                                  >
                                    🗑️
                                  </button>
                                </div>
                              </div>
                            ))
                        ) : (
                          <div className="empty-folder">
                            <div className="empty-folder-item"></div>
                            <div className="empty-folder-item"></div>
                            <div className="empty-folder-item"></div>
                            <div className="empty-folder-item"></div>
                            <div className="empty-folder-item"></div>
                          </div>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>

            <div className="privacy-section">
              <h3>Настройки приватности</h3>
              <div className="privacy-options">
                <div className="privacy-option">
                  <label className="privacy-label">
                    <input
                      type="radio"
                      name="privacy"
                      value="public"
                      checked={isPublic}
                      onChange={() => handlePrivacyChange(true)}
                      disabled={savingPrivacy}
                    />
                    <span className="privacy-text">
                      <strong>Публичный</strong>
                      <small>Проект виден всем пользователям</small>
                    </span>
                  </label>
                </div>
                <div className="privacy-option">
                  <label className="privacy-label">
                    <input
                      type="radio"
                      name="privacy"
                      value="private"
                      checked={!isPublic}
                      onChange={() => handlePrivacyChange(false)}
                      disabled={savingPrivacy}
                    />
                    <span className="privacy-text">
                      <strong>Приватный</strong>
                      <small>Проект виден только вам</small>
                    </span>
                  </label>
                </div>
              </div>
              {savingPrivacy && (
                <div className="saving-indicator">Сохранение...</div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ProjectFileModal;
